from pathlib import Path
import json,sys
base=Path('outputs/Шнек 1 — параметрическая модель').resolve();sys.path.insert(0,str(base));import journal
state=json.loads((base/'state.json').read_text(encoding='utf-8'));rows=json.loads((base/'geometry_rebuild_latest.json').read_text(encoding='utf-8'));audit=json.loads((base/'parameter_correspondence_20261005.json').read_text(encoding='utf-8'))
assert len(rows)==3 and all(r['applied'] for r in rows),rows
assert all(r['match'] for r in audit['parameters']+audit['bindings'])
assert state['values']['incline']==55 and state['values']['tube_diameter']==133
p=base/'README.md';s=p.read_text(encoding='utf-8');start=s.index('## Последняя проверка');end=s.index('## Запуск',start)
section="""## Последняя проверка — 05.10.2026

Сохранена и проверена рабочая сборка: **длина 2510 мм, труба Ø133×4 мм, винт Ø121 мм, наклон 55° от горизонтали**. 204 компонента, 0 подавленных компонентов, 0 ошибок элементов и сопряжений, 0 объёмных пересечений более 0,001 мм³ в представлении с условной резьбой. Целевой угол проекта достигнут. Исходная CAD-переменная задаёт угол от вертикали; интерфейс записывает `90° − угол формы`.

Причины отказа устранены в CAD: высота ушей и их седло зависят от диаметра трубы; ось верхнего патрубка, его базовая плоскость и профиль выреза — от длины и угла корпуса. Первый подкос получил непрерывный обход корпуса; второй обновляется через зеркальное построение. Каждый подкос имеет одно тело, места крепления сохранены. Новая форма подкосов и её сварные соединения требуют расчёта прочности; геометрическая проверка его не заменяет. Проход подкосов выполнен под фиксированную проверенную оболочку Ø147 мм; полный диапазон диаметра и угла не подтверждён.

| Параметр | Проверенный цикл | Результат |
|---|---|---|
| Рабочая длина | 2510 → 2610 → 2510 мм | Ошибок и пересечений нет |
| Диаметр трубы | 133 → 141 → 133 мм | Ошибок и пересечений нет |
| Наклон | 55 → 35 → 55° | Ошибок и пересечений нет |

В заключительном испытании три параметра изменены одновременно: 2610 мм, Ø141 мм, 35°. Затем пользовательские значения 2510 мм, Ø133 мм, 55° восстановлены, проверены и сохранены. Сопоставлены все 18 параметров операций и {binding_count} связанных размеров. Отверстие Ø110 мм сохранено, деталь сбрасывателя отсутствует. M8 задаёт отверстия Ø8,8 мм. Габарит патрубка после подрезки отличается от заданной длины вытягивания.

Протоколы: `brace_clearance_fix_20261005.json`, `brace_transition_fix_20261005.json`, `geometry_rebuild_latest.json`, `parameter_correspondence_20261005.json`. Предыдущие результаты сохранены в архивных протоколах: `geometry_rebuild_before_dependency_repair_20261005.json` и `parameter_correspondence_before_rebuild_dependencies_20261005.json`. Они описывают состояние до исправления.

Результат кнопки **Применить к модели** показан постоянно: фактически сохранённые размеры, запрошенные размеры при отказе, ошибки операций или пересечения и результат проверенного отката. Сообщение сохраняется после обновления страницы. При недоступной кнопке рядом показана причина: пустое поле, несовместимые размеры или ограничение угла. Во время применения повторный запуск блокируется.

""".format(binding_count=len(audit['bindings']))
s=s[:start]+section+s[end:]
s=s.replace('Фактические 35° и целевые 55° сохраняются отдельно; для 55° по-прежнему требуется доработка геометрии.', 'Фактический угол 55° теперь совпадает с целевым. Допустимый ввод не означает, что весь диапазон геометрии проверен.')
s=s.replace('сохранённая CAD-сборка имеет 35° от горизонтали.', 'сохранённая CAD-сборка имеет 55° от горизонтали.')
s=s.replace('При текущей геометрии и 190 об/мин геометрический предел равен 14,67 м³/ч, требуемая доля — 68,17%; фактическая подача не подтверждена.', 'Текущий геометрический предел и требуемая доля фактической подачи рассчитываются в интерфейсе при изменении геометрии; фактическая подача не подтверждена.')
s=s.replace('оси этих патрубков образуют с осью корпуса острый угол 55°', 'оси этих патрубков при наклоне 55° образуют с осью корпуса острый угол 35°')
s=s.replace('проверить диапазон диаметров, доработать изменение угла и опору для целевых 55°,', 'проверить полный диапазон параметров, рассчитать новые подкосы и их соединения,')
p.write_text(s,encoding='utf-8')
identity='rebuild-repaired-roundtrips-20261005'
if not any(e.get('verification_id')==identity for e in journal._read()['entries']):
 names={'working_length':'Рабочая длина','tube_diameter':'Диаметр трубы','incline':'Угол наклона'}
 journal._append({'type':'model_check','title':'Перестроение после исправления: длина, диаметр, угол','verification_id':identity,'change_count':0,'check_count':3,'changes':[{'key':r['parameter'],'name':names[r['parameter']],'before':str(r['before'])+' → '+str(r['tested'])+' → '+str(r['before']),'after':'Перестроено, восстановлено и сохранено; 0 ошибок и пересечений'} for r in rows]})
print('Current verification documented, bindings',len(audit['bindings']))
